#[local] Abbreviation TX_len := (PECSRD1U.TX_len L HI LY HIok R0 M0 model0 K LBX cr0 S r fb len s0 str sm0 pl tl Rra0 RAok Rsp0 Rgp0 Rtp0 K0 FR1 FR2 FR3 Hlen INCS UNS0 POK TL0 POS0 RSZ FB FBT KONT).
