Lemma at_srcread mu0 (IH : IHt mu0) (fx : FPState) R M model s sm cr (w k n p : Z) :
  getr R (reg 1) = Z_to_bv 64 245176 -> getr R (reg 2) = Z_to_bv 64 (S - 80) -> getr R (reg 8) = Z_to_bv 64 len -> getr R (reg 9) = Z_to_bv 64 (fb + 376) ->
  getr R (reg 10) = Z_to_bv 64 (fb + 64) -> getr R (reg 11) = Z_to_bv 64 p -> getr R (reg 12) = Z_to_bv 64 k ->
  getr R (reg 18) = Z_to_bv 64 (fb + 64) -> getr R (reg 19) = Z_to_bv 64 k ->
  getr R (reg 21) = Z_to_bv 64 w -> getr R (reg 22) = Z_to_bv 64 (fb + 376 + 1) -> getr R (reg 23) = Z_to_bv 64 n -> kept6 R ->
  1 <= k <= w -> k <= PM.CHUNK -> w <= len -> tbdst s p k -> p = PM.vs_data (fb + 376) (PM.p_tb s) + n ->
  state_ok M model s sm cr -> PM.vs_size (PM.p_tb s) = n + k -> 0 <= n -> n = PM.vs_size (PM.p_tb s0) + (len - w) ->
  PMSP.consumed (PM.p_src s0) (PM.p_src s) sm0 sm = len - w ->
  PMSP.src_step (PM.p_src s0) (PM.p_src s) sm0 sm -> fields_eq s -> TX M (PM.p_tb s) (len - w) ->
  (1 <= PM.sr_rem (PM.p_src s) \/ PM.sm_st sm = 0) -> PM.mu_src (PM.p_src s) sm <= mu0 ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x3a9c0 M model) K.
